css:
/* Before / after: two photos stacked, the "after" one clipped at --ba-pos. With no script (and on the
   Design canvas) it sits at 50%, which is the resting state. The script only moves --ba-pos. */
[data-bz-node="ba-band"] > .bz-container { max-width: min(90vw, 1440px); background: #ebf7ff; padding: 42px 0 26px; }
[data-bz-section="before-after"] .bz-block { padding-block: 0; }
[data-bz-section="before-after"] [data-bz-node="ba-stage"] { --ba-pos: 50%; position: relative; width: 100%; max-width: 719px; margin: 0 auto; aspect-ratio: 3 / 2; overflow: hidden; background: #000; touch-action: pan-y; }
[data-bz-section="before-after"] [data-bz-node="ba-stage"] > .bz-block, [data-bz-section="before-after"] [data-bz-node="ba-stage"] .bz-container { position: absolute; inset: 0; margin: 0; padding: 0; max-width: none; }
[data-bz-section="before-after"] [data-bz-node="ba-stage"] .bz-figure, [data-bz-section="before-after"] [data-bz-node="ba-stage"] img { display: block; width: 100%; height: 100%; margin: 0; object-fit: cover; border-radius: 0; }
[data-bz-section="before-after"] [data-bz-node="ba-after"] { clip-path: inset(0 0 0 var(--ba-pos)); }
[data-bz-section="before-after"] [data-bz-node="ba-before-label"], [data-bz-section="before-after"] [data-bz-node="ba-after-label"] { inset: 26px auto auto 25px; z-index: 2; pointer-events: none; }
[data-bz-section="before-after"] [data-bz-node="ba-after-label"] { inset: 26px 25px auto auto; }
[data-bz-section="before-after"] [data-bz-node="ba-before-label"] .bz-text p, [data-bz-section="before-after"] [data-bz-node="ba-after-label"] .bz-text p { margin: 0; font: 400 0.7rem / 1 var(--font-body); color: #fff; text-shadow: 0 0 3px rgba(0, 0, 0, 0.7); }
[data-bz-section="before-after"] [data-bz-node="ba-stage"]::before { content: ""; position: absolute; z-index: 3; top: 0; bottom: 0; left: var(--ba-pos); width: 3px; margin-left: -1px; background: #fff; pointer-events: none; }
[data-bz-section="before-after"] [data-bz-node="ba-stage"]::after { content: "\25C2\25B8"; position: absolute; z-index: 3; top: 50%; left: var(--ba-pos); width: 38px; height: 38px; margin: -19px 0 0 -19px; box-sizing: border-box; border: 2px solid #fff; border-radius: 50%; background: rgba(0, 0, 0, 0.25); color: #fff; font: 400 0.7rem / 34px var(--font-body); letter-spacing: 1px; text-align: center; pointer-events: none; }
[data-bz-section="before-after"] [data-bz-node="ba-caption"] .bz-text p { margin: 37px 0 0; text-align: center; font: italic 400 0.84rem / 1.4 var(--font-body); color: #222; max-width: none; }

js:
/* Before / after: follow the pointer (or arrow keys) across the photo. */
(function () {
  document.querySelectorAll('[data-bz-section="before-after"] [data-bz-node="ba-stage"]').forEach(function (stage) {
    if (stage.__bzBA) return;
    stage.__bzBA = true;
    var pos = 50;
    function set(p) {
      pos = Math.max(0, Math.min(100, p));
      stage.style.setProperty('--ba-pos', pos + '%');
      stage.setAttribute('aria-valuenow', String(Math.round(pos)));
    }
    stage.setAttribute('role', 'slider');
    stage.setAttribute('tabindex', '0');
    stage.setAttribute('aria-label', 'Before and after');
    stage.setAttribute('aria-valuemin', '0');
    stage.setAttribute('aria-valuemax', '100');
    stage.setAttribute('aria-valuenow', '50');
    function fromEvent(e) {
      var r = stage.getBoundingClientRect();
      set(((e.clientX - r.left) / r.width) * 100);
    }
    stage.addEventListener('pointermove', fromEvent);
    stage.addEventListener('pointerdown', fromEvent);
    stage.addEventListener('keydown', function (e) {
      if (e.key === 'ArrowLeft') { set(pos - 5); e.preventDefault(); }
      if (e.key === 'ArrowRight') { set(pos + 5); e.preventDefault(); }
    });
  });
})();
